{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 1,
      "content": {
        "json": "# Homelab Security Operations\n\nDetection-engineering metrics across **Microsoft Sentinel + Defender XDR**. Everything below is deployed **as code** (Sigma -> CI/CD -> Sentinel/Defender): 5 scheduled analytics rules, 5 Defender custom detections, a SOAR notification playbook, and 3 threat-intelligence feeds. Use the time range to scope the incident/alert tiles."
      },
      "name": "title"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "parameters": [
          {
            "id": "tr",
            "version": "KqlParameterItem/1.0",
            "name": "TimeRange",
            "label": "Time range",
            "type": 4,
            "value": { "durationMs": 2592000000 },
            "typeSettings": {
              "selectableValues": [
                { "durationMs": 86400000 },
                { "durationMs": 604800000 },
                { "durationMs": 2592000000 },
                { "durationMs": 7776000000 }
              ]
            }
          }
        ],
        "style": "pills"
      },
      "name": "parameters"
    },
    {
      "type": 1,
      "content": { "json": "## Overview" },
      "name": "h-overview"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "union isfuzzy=true\n (SecurityIncident | summarize Value = dcount(IncidentNumber) | extend Name = 'Incidents'),\n (SecurityIncident | where Status != 'Closed' | summarize Value = dcount(IncidentNumber) | extend Name = 'Open incidents'),\n (SecurityAlert | summarize Value = count() | extend Name = 'Alerts'),\n (ThreatIntelIndicators | summarize Value = count() | extend Name = 'TI indicators')\n| project Name, Value",
        "size": 3,
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "visualization": "tiles",
        "tileSettings": {
          "titleContent": { "columnMatch": "Name", "formatter": 1 },
          "leftContent": {
            "columnMatch": "Value",
            "formatter": 12,
            "formatOptions": { "palette": "blue" }
          },
          "showBorder": true
        }
      },
      "name": "overview-tiles"
    },
    {
      "type": 1,
      "content": { "json": "## Detections firing" },
      "name": "h-detections"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "SecurityAlert\n| extend Tactic = split(tostring(Tactics), ',')\n| mv-expand Tactic to typeof(string)\n| extend Tactic = trim(' ', Tactic)\n| where isnotempty(Tactic)\n| summarize Alerts = count() by Tactic\n| order by Alerts desc",
        "size": 1,
        "title": "Alerts by ATT&CK tactic",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "visualization": "barchart"
      },
      "customWidth": "50",
      "name": "alerts-by-tactic"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "SecurityAlert\n| summarize Alerts = count(), LastSeen = max(TimeGenerated) by Detection = AlertName, Severity = AlertSeverity\n| order by Alerts desc",
        "size": 1,
        "title": "Alerts by detection",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "visualization": "table",
        "gridSettings": {
          "formatters": [
            { "columnMatch": "Alerts", "formatter": 8, "formatOptions": { "palette": "blue" } },
            { "columnMatch": "Severity", "formatter": 18, "formatOptions": { "thresholdsOptions": "colors", "thresholdsGrid": [
              { "operator": "==", "thresholdValue": "High", "representation": "redBright", "text": "{0}{1}" },
              { "operator": "==", "thresholdValue": "Medium", "representation": "orange", "text": "{0}{1}" },
              { "operator": "Default", "representation": "gray", "text": "{0}{1}" }
            ] } }
          ]
        }
      },
      "customWidth": "50",
      "name": "alerts-by-detection"
    },
    {
      "type": 1,
      "content": { "json": "## Incidents" },
      "name": "h-incidents"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "SecurityIncident\n| summarize arg_max(TimeGenerated, Severity) by IncidentNumber\n| summarize Incidents = count() by Severity, bin(TimeGenerated, 1d)\n| order by TimeGenerated asc",
        "size": 1,
        "title": "Incidents over time by severity",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "visualization": "barchart",
        "chartSettings": { "group": "Severity", "createOtherGroup": 0 }
      },
      "customWidth": "50",
      "name": "incidents-trend"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "SecurityIncident\n| summarize arg_max(TimeGenerated, *) by IncidentNumber\n| summarize Incidents = count() by Severity, Status",
        "size": 1,
        "title": "Incidents by severity & status",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "visualization": "table"
      },
      "customWidth": "50",
      "name": "incidents-status"
    },
    {
      "type": 1,
      "content": { "json": "## Threat intelligence feed health\n\nThree feeds ingested as code: **MDTI** (connector), **AlienVault OTX** (TAXII), **abuse.ch ThreatFox** (STIX upload pipeline)." },
      "name": "h-ti"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ThreatIntelIndicators\n| summarize Indicators = count() by Feed = SourceSystem\n| order by Indicators desc",
        "size": 1,
        "title": "Indicators by feed",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "visualization": "piechart"
      },
      "customWidth": "50",
      "name": "ti-by-feed"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ThreatIntelIndicators\n| where isnotempty(ObservableKey)\n| summarize Indicators = count() by Type = tostring(ObservableKey)\n| order by Indicators desc\n| take 10",
        "size": 1,
        "title": "Indicator types (top 10)",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "visualization": "barchart"
      },
      "customWidth": "50",
      "name": "ti-by-type"
    }
  ],
  "$schema": "https://github.com/Microsoft/Application-Insights-Workbooks/blob/master/schema/workbook.json"
}
